def word_frequency(text: str) -> dict[str, int]:
    import string
    freq = {}
    for word in text.split():
        cleaned = word.strip(string.punctuation).lower()
        if cleaned:
            freq[cleaned] = freq.get(cleaned, 0) + 1
    return freq
